            e.jsx("h3", { className: "font-extrabold text-slate-800 text-base", children: "Grafik Realisasi Pembayaran SPP per Tingkat Kelas (Kelas 1 - Kelas 6)" }),
            e.jsx("p", { className: "text-xs text-slate-500", children: "Perbandingan nominal SPP yang sudah lunas (Hijau) dan sisa tunggakan (Merah) per rombel" })
